import{_ as a,o as i,c as t,a0 as e}from"./chunks/framework.DoRPXVp_.js";const c=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),n={name:"guide/quickstart.md"};function l(h,s,p,d,o,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>10 分钟内在单机拉起控制面，并让一台设备加入 mesh。</p><h2 id="_0-准备" tabindex="-1">0. 准备 <a class="header-anchor" href="#_0-准备" aria-label="Permalink to &quot;0. 准备&quot;">​</a></h2><ul><li>已按<a href="/guide/installation">安装指南</a>装好 <code>lattice</code>（客户端）并能构建 <code>latticed</code>（控制面）</li><li>本机试用只需一台机器；要让局域网其它设备加入，先想好它们访问本机用的地址（下文用 <code>192.168.1.8</code> 举例，换成你的局域网 IP）</li></ul><h2 id="_1-启动控制面-standalone-模式" tabindex="-1">1. 启动控制面（standalone 模式） <a class="header-anchor" href="#_1-启动控制面-standalone-模式" aria-label="Permalink to &quot;1. 启动控制面（standalone 模式）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SERVICE=latticed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 首次会先打包前端</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/latticed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --standalone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .lattice-demo</span></span></code></pre></div><p>看到 <code>All systems go! Latticed is ready.</code> 即启动完成：</p><ul><li><strong>Dashboard / API</strong>：<code>http://localhost:8080</code></li><li>内嵌 NATS 信令 <code>:4222</code>、LRP 中继 <code>:6266</code>（standalone 模式下都在本进程内）</li><li>数据库 <code>lattice.db</code> 落在<strong>启动时的工作目录</strong>——固定用同一个目录启动，换目录等于换库</li></ul><p><strong>要让其它设备加入</strong>，用环境变量把&quot;下发给设备的地址&quot;指向它们可达的地址（这是最常见的踩坑点，默认回环地址只有本机能用）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LATTICE_LISTEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.0.0.0:8080</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LATTICE_SIGNALING_URL=nats://192.168.1.8:4222 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LATTICE_RELAY_ADVERTISE_URL=192.168.1.8:6266 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">./bin/latticed </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--standalone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .lattice-demo</span></span></code></pre></div><p>打开 Dashboard，用初始管理员 <code>admin / 123456</code> 登录，<strong>立即修改密码</strong>。</p><h2 id="_2-签发入网令牌" tabindex="-1">2. 签发入网令牌 <a class="header-anchor" href="#_2-签发入网令牌" aria-label="Permalink to &quot;2. 签发入网令牌&quot;">​</a></h2><p>Dashboard → <strong>令牌</strong> 页面 → 生成令牌。令牌行菜单里可以直接生成<strong>入网二维码</strong>（手机 App 扫码用）。</p><p>也可以用 API 创建工作区和令牌，见<a href="/deploy/end-to-end">全流程部署</a>的&quot;首次登录&quot;一节。</p><h2 id="_3-设备加入" tabindex="-1">3. 设备加入 <a class="header-anchor" href="#_3-设备加入" aria-label="Permalink to &quot;3. 设备加入&quot;">​</a></h2><p><strong>命令行（macOS / Linux）：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.1.8:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">入网令</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">牌</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 需要 root 创建 WireGuard 网卡</span></span></code></pre></div><p><code>lattice init</code> 交互式回答服务器地址和令牌也行；NATS 信令地址会通过 <code>/api/v1/discovery</code> 自动发现，不用手填。</p><p><strong>手机 / Mac App：</strong> 打开 App → 扫描令牌页的入网二维码（内容为 <code>lattice://join?server=&lt;面板地址&gt;&amp;token=&lt;令牌&gt;</code>），首次连接允许系统弹出的 VPN 授权。Apple 客户端从源码构建，见<a href="/deploy/end-to-end">全流程部署 · macOS / iOS</a>。</p><h2 id="_4-验证" tabindex="-1">4. 验证 <a class="header-anchor" href="#_4-验证" aria-label="Permalink to &quot;4. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>设备应显示已分配的覆盖网络地址（<code>10.96.0.x</code>）和对端列表；Dashboard 的设备页也能看到。两台设备互相 ping：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.96.0.x</span></span></code></pre></div><p><code>status</code> 里 <code>Path: direct</code> 表示直连（ICE 打洞成功），<code>relayed</code> 表示走了中继。</p><h2 id="_5-下一步" tabindex="-1">5. 下一步 <a class="header-anchor" href="#_5-下一步" aria-label="Permalink to &quot;5. 下一步&quot;">​</a></h2><ul><li><strong>公网云主机部署 + Mac/iPhone 三端接入</strong>：<a href="/deploy/end-to-end">全流程部署</a></li><li><strong>家庭/个人模式</strong>（回家可用、出门也可控）：<a href="/deploy-personal-mode">个人模式部署</a></li><li><strong>客户端更多用法</strong>（daemon、容器节点、workspace/token/policy 管理）：<a href="/guide/agent">Agent Setup</a></li><li><strong>Kubernetes 部署</strong>：<a href="/deploy/helm">Helm</a> · <a href="/deploy/k8s-operator">Kustomize</a></li></ul>`,26)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
